 10	import {
 11	  BookletConfig, type BookletMetadata, type BookletStateDef, type BookletStateOptionDef, type ContextInBooklet, type TestletDef, type UnitDef
 12	} from '../../shared/shared.module';
 13	
 14	@Injectable()
 15	export class BookletService extends BookletParserService<Unit, Testlet, BookletStateOption, BookletState, Booklet> {
 16	  private readonly booklets: { [k: string]: Observable<Booklet | BookletError> } = {};
 17	
 18	  constructor(private bs: BackendService) {
 19	    super();
 20	  }
 21	
 22	  private accessIdentity: unknown;
 23	  getBooklet(bookletName = ''): Observable<Booklet | BookletError> {
 24	    bookletName = nativeMonitorBookletFileId(bookletName);
 25	    if (this.accessIdentity !== this.bs.cacheIdentity) {
 26	      for (const name of Object.keys(this.booklets)) delete this.booklets[name];
 27	      this.accessIdentity = this.bs.cacheIdentity;
 28	    }
 29	    if (typeof this.booklets[bookletName] !== 'undefined') {
 30	      return this.booklets[bookletName];
 31	    }
 32	    if (bookletName === '') {
 33	      this.booklets[bookletName] = of<Booklet | BookletError>({ error: 'missing-id', species: null });
 34	    } else {
 35	      const identity = this.accessIdentity;
 36	      const scope = this.bs.accessSignal;
 37	      const request = defer(() => scope.aborted || identity !== this.bs.cacheIdentity ? EMPTY : this.bs.getBooklet(bookletName)).pipe(
 38	        map((response: string | BookletError) => (typeof response === 'string' ? this.parseXml(response) : response)),
 39	        tap(booklet => {
 40	          // Retry failures later; an old request must not evict a new access's cache.
 41	          if (this.booklets[bookletName] === request) {
 42	            if (isBooklet(booklet)) this.booklets[bookletName] = of(booklet);
 43	            else delete this.booklets[bookletName];
 44	          }
 45	        }),
 46	        // Snapshot replacement must not starve slow material. Explicit
 47	        // connection/access cancellation still aborts the underlying read.
 48	        takeUntil(merge(this.bs.connectionClosed$, fromEvent(scope, 'abort'))),
 49	        finalize(() => {
 50	          if (this.booklets[bookletName] === request) delete this.booklets[bookletName];
 51	        }),
 52	        shareReplay({ bufferSize: 1, refCount: false })
 53	      );
 54	      this.booklets[bookletName] = request;
 55	    }
 56	    return this.booklets[bookletName];
 57	  }
 58	
 59	  parseXml(xmlString: string): Booklet | BookletError {
 60	    try {
 61	      return this.parseBookletXml(xmlString);
 62	    } catch (error) {
 63	      return { error: 'xml', species: null };
 64	    }
 65	  }
 66	
 67	  toBooklet(
 68	    metadata: BookletMetadata,
 69	    config: BookletConfig,
 70	    customTexts: { [key: string]: string },
 71	    states: { [key: string]: BookletState },
