 98	  override toBookletState(stateDef: BookletStateDef<BookletStateOption>): BookletState {
 99	    const defaultOption = Object.values(stateDef.options).find(option => !option.conditions.length);
100	    return Object.assign(stateDef, {
101	      default: defaultOption?.id || Object.values(stateDef.options)[0].id
102	    });
103	  }
